const fs = require('fs');

function main() {
  const path = process.argv[2];
  const buf = fs.readFileSync(path);

  if (buf.length < 64 || buf.readUInt32LE(0) !== 0x464c457f) {
    console.log('{}');
    return;
  }

  const e_phoff = Number(buf.readBigUInt64LE(32));
  const e_phentsize = buf.readUInt16LE(54);
  const e_phnum = buf.readUInt16LE(56);

  const segs = [];
  for (let i = 0; i < e_phnum; i++) {
    const off = e_phoff + i * e_phentsize;
    const p_type = buf.readUInt32LE(off + 0);
    const p_offset = Number(buf.readBigUInt64LE(off + 8));
    const p_vaddr = Number(buf.readBigUInt64LE(off + 16));
    const p_filesz = Number(buf.readBigUInt64LE(off + 32));
    const p_memsz = Number(buf.readBigUInt64LE(off + 40));
    if (p_type === 1) { // PT_LOAD
      segs.push({ p_offset, p_vaddr, p_filesz, p_memsz });
    }
  }

  if (segs.length === 0) {
    console.log('{}');
    return;
  }

  let min = Infinity, max = 0;
  for (const s of segs) {
    if (s.p_vaddr < min) min = s.p_vaddr;
    if (s.p_vaddr + s.p_memsz > max) max = s.p_vaddr + s.p_memsz;
  }
  min = Math.ceil(min / 4) * 4;

  function byteAt(v) {
    for (const s of segs) {
      if (v >= s.p_vaddr && v < s.p_vaddr + s.p_filesz) {
        return buf[s.p_offset + (v - s.p_vaddr)];
      }
    }
    return 0;
  }

  const out = {};
  for (let a = min; a + 4 <= max; a += 4) {
    const b0 = byteAt(a), b1 = byteAt(a + 1), b2 = byteAt(a + 2), b3 = byteAt(a + 3);
    const val = (b0 | (b1 << 8) | (b2 << 16) | (b3 << 24)) >>> 0;
    out[a] = val;
  }

  const sorted = {};
  Object.keys(out).map(Number).sort((x, y) => x - y).forEach(k => { sorted[k] = out[k]; });

  console.log(JSON.stringify(sorted));
}

main();
EOF

